function solve({config,state,event}) {
  const s = Array.isArray(state) ? state : [];
  const t = event && event.type;
  if (t === "save") {
    for (let i = 0; i < s.length; i++) {
      if (s[i].id === event.id) { s.splice(i, 1); break; }
    }
    s.push({id:event.id, data:event.data.slice(), checksum:event.checksum});
    while (s.length > config.keep) s.shift();
  } else if (t === "damage") {
    for (let i = 0; i < s.length; i++) {
      const x = s[i];
      if (x.id === event.id) {
        const j = event.index;
        if (Number.isInteger(j) && j >= 0 && j < x.data.length) x.data[j] = event.value;
        break;
      }
    }
  } else if (t === "drop") {
    for (let i = 0; i < s.length; i++) {
      if (s[i].id === event.id) { s.splice(i, 1); break; }
    }
  }
  let data = null, chosen = null;
  if (t === "restore") {
    for (let i = s.length - 1; i >= 0; i--) {
      const x = s[i];
      let sum = 0;
      for (let j = 0; j < x.data.length; j++) sum = (sum + (j + 1) * x.data[j]) % 251;
      if (sum === x.checksum) {
        data = x.data.slice();
        chosen = x.id;
        break;
      }
    }
  }
  const retained = new Array(s.length);
  for (let i = 0; i < s.length; i++) retained[i] = s[i].id;
  return {state:s, output:{data:data, chosen:chosen, retained:retained}};
}
